<?php
require_once 'inc/db.php';require_once 'inc/auth.php';if((int)$_SESSION['role_id']!==1){http_response_code(403);die('Access denied.');}$msg='';if($_SERVER['REQUEST_METHOD']==='POST'&&!empty(trim($_POST['name']??''))){$db->prepare('INSERT INTO tbl_damage_types(type_name,description) VALUES(?,?)')->execute([trim($_POST['name']),trim($_POST['description']??'')]);$msg='Damage type added.';}$types=$db->query('SELECT dt.*,COUNT(r.report_id) reports FROM tbl_damage_types dt LEFT JOIN tbl_road_reports r ON r.damage_type_id=dt.type_id GROUP BY dt.type_id ORDER BY dt.type_name')->fetchAll(PDO::FETCH_ASSOC);$page_title='Damage Types';include 'inc/links.php';include 'inc/header.php';?>
<div class="inner-wrapper"><?php include 'inc/sidebar.php';?><section role="main" class="content-body"><?php include 'inc/inner-header.php';?><?php if($msg):?><div class="alert alert-success"><?php echo e($msg);?></div><?php endif;?><div class="row"><div class="col-md-5"><section class="panel"><header class="panel-heading"><h2 class="panel-title">Add Classification</h2></header><div class="panel-body"><form method="post"><div class="form-group"><label>Name</label><input required name="name" class="form-control"></div><div class="form-group"><label>Description</label><textarea name="description" class="form-control"></textarea></div><button class="btn btn-danger">Add Type</button></form></div></section></div><div class="col-md-7"><section class="panel"><header class="panel-heading"><h2 class="panel-title">Classification Catalogue</h2></header><div class="panel-body"><?php foreach($types as $t):?><div class="analytic-row"><span><strong><?php echo e($t['type_name']);?></strong><br><small><?php echo e($t['description']);?></small></span><span class="badge"><?php echo (int)$t['reports'];?> reports</span></div><?php endforeach;?></div></section></div></div></section></div><?php include 'inc/scripts.php';?>
